#!/usr/bin/env python3
"""Print nfkc_table.go: the code points whose NFKC form contains one of / ? # @ :

urllib.parse._checknetloc rejects a netloc containing such a character. Run on the test server:

    ~/cf-test/.venv/bin/python server/internal/urlx/testdata/gen_nfkc.py > server/internal/urlx/nfkc_table.go
"""
import sys
import unicodedata

assert sys.version_info[:2] == (3, 11)
chars = []
for cp in range(0x80, 0x110000):
    if 0xD800 <= cp <= 0xDFFF:
        continue
    text = chr(cp)
    folded = unicodedata.normalize('NFKC', text)
    if folded != text and any(c in folded for c in '/?#@:'):
        chars.append(cp)
print('// Code generated by testdata/gen_nfkc.py (Python %s, Unicode %s); DO NOT EDIT.' % (sys.version.split()[0], unicodedata.unidata_version))
print()
print('package urlx')
print()
print('// netlocUnsafe lists the code points whose NFKC normalization contains one of / ? # @ :')
print('// (urllib.parse._checknetloc).')
print('var netlocUnsafe = map[rune]bool{')
for cp in chars:
    print('\t0x%X: true,' % cp)
print('}')
